1	// Regression coverage for AuditPage against a root checkpoint: the
2	// sequence-0 checkpoint whose fingerprint is the organization's genesis
3	// fingerprint, handed out by the first AuditQuery or AuditExport of an
4	// organization that has not yet produced any audit records.
5	//
6	// That checkpoint pins a finished empty range, and the answer must not
7	// depend on the store's incidental state:
8	//
9	//   - Whether the store has never visited the organization, has only run an
10	//     empty query/export against it, or has since appended records, cursor 0
11	//     (exhausted) and cursor 1 (the one-past-end end page) both succeed with
12	//     an empty page: Next 0, BeginSeq 1, EndSeq 0, and the page's org and
13	//     checkpoint returned exactly as submitted. Cursor 1 is the end page,
14	//     not an out-of-range error and not a restart.
15	//   - The empty range still rests on real checkpoint material: a foreign
16	//     organization's root fingerprint or any other wrong value fails with
17	//     ErrInvalidRange and delivers no page, at both cursors. A cursor above 1
18	//     claims records the root checkpoint says do not exist and fails the same
19	//     way, as does an EndSeq > 0 checkpoint against a recordless chain.
20	//   - Once pinned at sequence 0, records the organization produces later
21	//     never enter the old range and the checkpoint is never re-stamped to
22	//     the current tail; only a fresh query sees the new records.
23	//   - The empty outcome skips none of the existing argument validation:
24	//     missing organization, illegal page size or cursor, unknown category
25	//     and duplicate resource conditions still fail before any page exists.
26	//
27	// Every call here is read-only: it appends no audit record and moves no
28	// policy version.
29	package darksafe
30	
31	import (
32		"errors"
33		"reflect"
34		"testing"
35	)
36	
37	// rootCheckpoint builds the sequence-0 checkpoint a first AuditQuery or
38	// AuditExport returns for an empty organization.
39	func rootCheckpoint(org string) Checkpoint {
40		return Checkpoint{Org: org, EndSeq: 0, Fingerprint: genesisFingerprint(org)}
41	}
42	
43	// requireEmptyRootPage fails unless the page is the uniform empty end page
44	// for a root checkpoint: nil error, no records, Next 0, BeginSeq 1,
45	// EndSeq 0, org and checkpoint byte-for-byte as submitted.
46	func requireEmptyRootPage(t *testing.T, page *AuditPage, err error, cp Checkpoint) {
47		t.Helper()
48		if err != nil {
49			t.Fatalf("root checkpoint paging err = %v, want nil", err)
50		}
51		if page == nil {
52			t.Fatal("root checkpoint paging delivered nil page with nil error")
53		}
54		if len(page.Records) != 0 {
55			t.Fatalf("root page delivered %d records %v, want none", len(page.Records), recordSeqs(page.Records))
56		}
57		if page.Next != 0 {
58			t.Fatalf("root page next = %d, want 0", page.Next)
59		}
60		if page.BeginSeq != 1 {
61			t.Fatalf("root page begin = %d, want 1", page.BeginSeq)
62		}
63		if page.EndSeq != 0 {
64			t.Fatalf("root page end = %d, want 0", page.EndSeq)
65		}
66		if page.Org != cp.Org {
67			t.Fatalf("root page org = %q, want %q", page.Org, cp.Org)
68		}
69		if page.Checkpoint != cp {
70			t.Fatalf("root page checkpoint = %+v, want submitted %+v", page.Checkpoint, cp)
71		}
72	}
73	
74	// TestAuditPageEmptyRootIsStateIndependent pins that the same root
75	// checkpoint produces the same empty end page whether the store has never
76	// seen the organization, has only queried/exported it empty, or has seen it
77	// via an empty query after an earlier rejection — read-only history never
78	// changes whether an identical paging request succeeds or what range it
79	// describes.
80	func TestAuditPageEmptyRootIsStateIndependent(t *testing.T) {
81		cp := rootCheckpoint("ghost")
82		cursors := []int{0, 1}
83	
84		// State 1: store that has never even visited the organization.
85		fresh := NewStore()
86		for _, cursor := range cursors {
87			page, err := fresh.AuditPage(cp, cursor, 10, "", "")
88			requireEmptyRootPage(t, page, err, cp)
89		}
90	
91		// State 2: store where an empty query first materialized the org.
92		queried := NewStore()
93		first, err := queried.AuditQuery("ghost", 1, 10, "", "")
94		if err != nil {
95			t.Fatal(err)
96		}
97		if first.Checkpoint != cp {
98			t.Fatalf("empty query checkpoint = %+v, want %+v", first.Checkpoint, cp)
99		}
100		for _, cursor := range cursors {
101			page, err := queried.AuditPage(cp, cursor, 10, "", "")
102			requireEmptyRootPage(t, page, err, cp)
103		}
104	
105		// State 3: store that reached the root checkpoint via an empty export.
106		exported := NewStore()
107		recs, exportCP, err := exported.AuditExport("ghost", 0)
108		if err != nil {
109			t.Fatal(err)
110		}
111		if len(recs) != 0 || exportCP != cp {
112			t.Fatalf("empty export = (%v, %+v), want no records and %+v", recs, exportCP, cp)
113		}
114		for _, cursor := range cursors {
115			page, err := exported.AuditPage(exportCP, cursor, 10, "", "")
116			requireEmptyRootPage(t, page, err, exportCP)
117		}
118	}
119	
120	// TestAuditPageEmptyRootRejectsUnreliableMaterial pins that the empty range
121	// gets no fingerprint exemption: any fingerprint other than this
122	// organization's sequence-0 root — including another organization's genuine
123	// root fingerprint — fails with ErrInvalidRange and delivers no page at
124	// either terminal cursor, and neither do out-of-range cursors or a
125	// checkpoint claiming positive records.
126	func TestAuditPageEmptyRootRejectsUnreliableMaterial(t *testing.T) {
127		s := NewStore()
128		cp := rootCheckpoint("ghost")
129	
130		// Wrong fingerprint value, same end sequence and org.
131		wrongValue := cp
132		wrongValue.Fingerprint = "00"
133		// Another organization's genuine root fingerprint must not validate
134		// under this organization's name: the fingerprint binds the organization.
135		foreignRoot := cp
136		foreignRoot.Fingerprint = genesisFingerprint("someone-else")
137	
138		for _, bad := range []Checkpoint{wrongValue, foreignRoot} {
139			for _, cursor := range []int{0, 1} {
140				page, err := s.AuditPage(bad, cursor, 10, "", "")
141				if !errors.Is(err, ErrInvalidRange) {
142					t.Fatalf("bad root %+v at cursor %d: err = %v, want ErrInvalidRange", bad, cursor, err)
143				}
144				if page != nil {
145					t.Fatalf("bad root %+v at cursor %d delivered page %+v", bad, cursor, page)
146				}
147			}
148		}
149	
150		// Sanity on the distinction above: that other organization's own
151		// consistent root checkpoint is a valid empty range for it — what makes
152		// foreignRoot invalid is the mismatch between name and fingerprint, not
153		// the fingerprint value in isolation.
154		other := rootCheckpoint("someone-else")
155		for _, cursor := range []int{0, 1} {
156			page, err := s.AuditPage(other, cursor, 10, "", "")
157			requireEmptyRootPage(t, page, err, other)
158		}
159	
160		// Cursor past the one-past-end position claims positive records that do
161		// not exist in the pinned range.
162		for _, cursor := range []int{2, 3, 100} {
163			page, err := s.AuditPage(cp, cursor, 10, "", "")
164			if !errors.Is(err, ErrInvalidRange) {
165				t.Fatalf("cursor %d on root checkpoint: err = %v, want ErrInvalidRange", cursor, err)
166			}
167			if page != nil {
168				t.Fatalf("cursor %d delivered page %+v", cursor, page)
169			}
170		}
171	
172		// A checkpoint claiming positive records cannot validate against an org
173		// that has none, even though its EndSeq would be a valid cursor shape.
174		claimsRecords := cp
175		claimsRecords.EndSeq = 1
176		claimsRecords.Fingerprint = "00"
177		for _, cursor := range []int{0, 1, 2} {
178			page, err := s.AuditPage(claimsRecords, cursor, 10, "", "")
179			if !errors.Is(err, ErrInvalidRange) {
180				t.Fatalf("positive-end checkpoint at cursor %d: err = %v, want ErrInvalidRange", cursor, err)
181			}
182			if page != nil {
183				t.Fatalf("positive-end checkpoint at cursor %d delivered page %+v", cursor, page)
184			}
185		}
186	
187		// The genuine root checkpoint is unaffected by the rejected attempts,
188		// and nothing about the rejected calls materialized the organization.
189		page, err := s.AuditPage(cp, 1, 10, "", "")
190		requireEmptyRootPage(t, page, err, cp)
191		if _, ok := s.orgs["ghost"]; ok {
192			t.Fatal("rejected/empty paging materialized the organization state")
193		}
194	}
195	
196	// TestAuditPageEmptyRootStaysClosedAfterRecordsAppend pins that a saved root
197	// checkpoint keeps describing its finished empty range after the
198	// organization grows: continued paging never mixes the new records in and
199	// never re-stamps the checkpoint to the current tail; only a fresh query
200	// observes the additions.
201	func TestAuditPageEmptyRootStaysClosedAfterRecordsAppend(t *testing.T) {
202		s := NewStore()
203	
204		// Obtain the root checkpoint through each of the two documented
205		// read-only entry points.
206		emptyQuery, err := s.AuditQuery("acme", 1, 10, "", "")
207		if err != nil {
208			t.Fatal(err)
209		}
210		queryCP := emptyQuery.Checkpoint
211		_, exportCP, err := s.AuditExport("acme", 0)
212		if err != nil {
213			t.Fatal(err)
214		}
215		if queryCP != rootCheckpoint("acme") || exportCP != queryCP {
216			t.Fatalf("root checkpoints = %+v / %+v, want equal genesis roots", queryCP, exportCP)
217		}
218	
219		// The organization later produces real audit records.
220		if _, err := s.Publish("acme", 0, []Policy{
221			allowPolicy("p-allow", "u1", "read", "org/a", false),
222		}); err != nil {
223			t.Fatal(err)
224		}
225		s.Decide("acme", request("acme", "u1", "r1", "org/a", "read")) // seq 2
226		if recs := drainAudit(t, s, "acme", "", ""); len(recs) != 2 {
227			t.Fatalf("chain = %v, want 2 appended records", recordSeqs(recs))
228		}
229	
230		// Both root checkpoints still answer the finished empty range from both
231		// terminal cursors, even with a filter that the appended decision would
232		// match in a fresh query.
233		for _, cp := range []Checkpoint{queryCP, exportCP} {
234			for _, cursor := range []int{0, 1} {
235				page, err := s.AuditPage(cp, cursor, 10, AuditDecision, "u1")
236				requireEmptyRootPage(t, page, err, cp)
237			}
238		}
239	
240		// A fresh query pins the new tail and sees the appended records; the old
241		// checkpoints are untouched by it.
242		fresh, err := s.AuditQuery("acme", 1, 10, "", "")
243		if err != nil {
244			t.Fatal(err)
245		}
246		if got := recordSeqs(fresh.Records); !reflect.DeepEqual(got, []int{1, 2}) {
247			t.Fatalf("fresh query records = %v, want [1 2]", got)
248		}
249		if fresh.Checkpoint.EndSeq != 2 || fresh.Checkpoint.Fingerprint == queryCP.Fingerprint {
250			t.Fatalf("fresh checkpoint = %+v, want end 2 with a non-genesis fingerprint", fresh.Checkpoint)
251		}
252		page, err := s.AuditPage(queryCP, 1, 10, "", "")
253		requireEmptyRootPage(t, page, err, queryCP)
254	
255		// All paging was read-only.
256		if got := recordSeqs(drainAudit(t, s, "acme", "", "")); !reflect.DeepEqual(got, []int{1, 2}) {
257			t.Fatalf("chain after root paging = %v, want [1 2]", got)
258		}
259		if v := s.CurrentVersion("acme"); v != 1 {
260			t.Fatalf("version = %d, want 1; root paging must not publish", v)
261		}
262	}
263	
264	// TestAuditPageEmptyRootKeepsArgumentValidation pins that the empty outcome
265	// skips none of the existing validation: missing organization, non-positive
266	// page size, negative cursor, unknown category and more than one resource
267	// condition are all rejected without delivering a page.
268	func TestAuditPageEmptyRootKeepsArgumentValidation(t *testing.T) {
269		cp := rootCheckpoint("ghost")
270	
271		if page, err := NewStore().AuditPage(Checkpoint{}, 0, 10, "", ""); !errors.Is(err, ErrMissingOrganization) || page != nil {
272			t.Fatalf("missing org = (%+v, %v), want nil page, ErrMissingOrganization", page, err)
273		}
274		if page, err := NewStore().AuditPage(cp, 0, 0, "", ""); !errors.Is(err, ErrInvalidPage) || page != nil {
275			t.Fatalf("zero page size = (%+v, %v), want nil page, ErrInvalidPage", page, err)
276		}
277		if page, err := NewStore().AuditPage(cp, -1, 10, "", ""); !errors.Is(err, ErrInvalidPage) || page != nil {
278			t.Fatalf("negative cursor = (%+v, %v), want nil page, ErrInvalidPage", page, err)
279		}
280		if page, err := NewStore().AuditPage(cp, 0, 10, "bogus", ""); !errors.Is(err, ErrInvalidPage) || page != nil {
281			t.Fatalf("unknown category = (%+v, %v), want nil page, ErrInvalidPage", page, err)
282		}
283		if page, err := NewStore().AuditPage(cp, 0, 10, "", "", "r1", "r2"); !errors.Is(err, ErrInvalidPage) || page != nil {
284			t.Fatalf("two resource conditions = (%+v, %v), want nil page, ErrInvalidPage", page, err)
285		}
286	}
